var e=`2026-10-11`,t={law:`Droit aérien`,met:`Météorologie`,nav:`Navigation`,perf:`Performances & préparation du vol`,pof:`Principes du vol`,agk:`Connaissance générale de l'aéronef`,hp:`Performances humaines`,ops:`Procédures opérationnelles`,com:`Communications`},n=JSON.parse(`{"q001":{"q":"Combien de temps une qualification de classe SEP (terrestre) est-elle valable ?","options":["12 mois","24 mois","36 mois","Illimitée"],"explain":"Les qualifications de classe monomoteur monopilote sont valables 24 mois.","hint":"Pense au rythme habituel de deux ans des qualifications de classe."},"q002":{"q":"Pour prolonger une qualification SEP par l'expérience, combien d'heures de vol faut-il dans les 12 mois avant l'échéance ?","options":["6 h","10 h","12 h","15 h"],"explain":"12 h dans la classe, dont 6 h comme PIC, 12 décollages et 12 atterrissages, plus un vol d'entraînement d'au moins 1 h avec un instructeur.","hint":"En moyenne une heure par mois sur la dernière année."},"q003":{"q":"Parmi ces heures pour la prolongation SEP par l'expérience, combien doivent être effectuées comme PIC ?","options":["3 h","6 h","8 h","12 h"],"explain":"Au moins 6 des 12 heures doivent être du temps PIC.","hint":"La moitié des heures exigées."},"q004":{"q":"Combien de décollages et d'atterrissages faut-il pour la prolongation SEP par l'expérience ?","options":["3 et 3","6 et 6","12 et 12","Aucun minimum"],"explain":"12 décollages et 12 atterrissages dans les 12 mois avant l'échéance.","hint":"En moyenne un décollage et un atterrissage par mois."},"q005":{"q":"Que faut-il en plus des heures et des atterrissages pour la prolongation SEP par l'expérience ?","options":["Un examen écrit","Un vol d'entraînement d'au moins 1 h avec un instructeur","Un vol de nuit","Un vol à l'étranger"],"explain":"Un vol d'entraînement de rafraîchissement d'au moins 1 heure avec un instructeur de vol (ou un instructeur de qualification de classe).","hint":"Quelque chose que tu fais avec un instructeur de vol."},"q006":{"q":"Avant d'emmener des passagers comme PIC, quelle expérience récente te faut-il ?","options":["1 décollage et 1 atterrissage ces 30 derniers jours","3 décollages et 3 atterrissages ces 90 derniers jours sur le même type ou la même classe","3 heures ces 90 derniers jours","5 décollages et 5 atterrissages ces 6 derniers mois"],"explain":"3 décollages, approches et atterrissages dans les 90 jours précédents sur un aéronef du même type ou de la même classe (ou en FFS).","hint":"Trois de chaque, en environ trois mois."},"q007":{"q":"Pour emmener des passagers de nuit comme PIC (sans qualification de vol aux instruments), au moins un des 3 décollages et atterrissages récents doit avoir eu lieu de nuit.","explain":"Sans IR valide, au moins 1 des 3 décollages et atterrissages des 90 derniers jours doit avoir eu lieu de nuit.","hint":"Qu'est-ce qui change la nuit par rapport au jour pour les passagers ?"},"q008":{"q":"Un pilote de 30 ans obtient un certificat médical de classe 2. Combien de temps est-il valable ?","options":["12 mois","24 mois","60 mois","Illimité"],"explain":"Classe 2 : 60 mois jusqu'à 40 ans, 24 mois de 40 à 50 ans, 12 mois après 50 ans. (Un certificat délivré avant 40 ans prend fin au plus tard à 42 ans.)","hint":"Les jeunes pilotes ont la plus longue validité – cinq ans."},"q009":{"q":"Combien de temps un certificat médical de classe 2 est-il valable pour un pilote de 45 ans ?","options":["12 mois","24 mois","36 mois","60 mois"],"explain":"Entre 40 et 50 ans : 24 mois.","hint":"Entre 40 et 50 ans, la validité est réduite à deux ans."},"q010":{"q":"Combien de temps un certificat médical de classe 2 est-il valable pour un pilote de 52 ans ?","options":["6 mois","12 mois","24 mois","60 mois"],"explain":"Après 50 ans : 12 mois.","hint":"Après 50 ans, tu vois le médecin-examinateur chaque année."},"q011":{"q":"La compétence linguistique de niveau 4 (fonctionnel) est valable :","options":["2 ans","4 ans","6 ans","Illimitée"],"explain":"Niveau 4 : 4 ans, niveau 5 : 6 ans, niveau 6 : pas de réévaluation nécessaire.","hint":"Le niveau 4 est le minimum opérationnel – il demande le contrôle le plus fréquent."},"q012":{"q":"La compétence linguistique de niveau 5 (avancé) est valable :","options":["4 ans","5 ans","6 ans","Illimitée"],"explain":"Le niveau 5 est valable 6 ans.","hint":"Niveau plus élevé = validité plus longue ; le niveau 6 n'expire jamais."},"q013":{"q":"Une PPL(A) a-t-elle elle-même une date d'expiration ?","options":["Oui, 5 ans","Oui, 10 ans","Non – mais les qualifications et le certificat médical doivent être valables pour l'utiliser","Oui, elle expire avec le certificat médical"],"explain":"La licence EASA n'a pas de date d'expiration. Pour exercer ses privilèges, la qualification de classe et le certificat médical doivent être valables.","hint":"Que renouvelles-tu vraiment – la licence ou ce qu'elle contient ?"},"q014":{"q":"Quels documents dois-tu avoir sur toi en tant que pilote en vol ?","options":["Ta licence","Ton certificat médical valable","Une pièce d'identité avec photo","Ton carnet de vol"],"explain":"Licence, certificat médical et pièce d'identité avec photo doivent être emportés. Le carnet de vol ne doit pas être à bord.","hint":"Pense : qui tu es, ce que tu peux piloter et si tu es apte médicalement."},"q015":{"q":"Lors d'un vol privé à frais partagés, les coûts directs peuvent être partagés entre au plus combien de personnes (pilote compris) ?","options":["2","4","6","9"],"explain":"Vols à frais partagés entre particuliers : coûts directs partagés par tous les occupants, pilote compris, au maximum 6 personnes.","hint":"Autant que les sièges de nombreux petits monomoteurs."},"q016":{"q":"Quel code transpondeur indique une panne de radio ?","options":["7000","7500","7600","7700"],"explain":"7600 = panne radio, 7700 = urgence, 7500 = intervention illicite.","hint":"Moyen mnémotechnique anglais : « Seven-six – radio fix » (radio en panne)."},"q017":{"q":"Quel code transpondeur indique une urgence ?","options":["7000","7500","7600","7700"],"explain":"7700 = urgence.","hint":"Moyen mnémotechnique anglais : « Seven-seven – going to heaven » (urgence)."},"q141":{"q":"Quel code transpondeur signale une intervention illicite (détournement) ?","options":["7000","7500","7600","7700"],"explain":"7500 = intervention illicite, 7600 = panne radio, 7700 = urgence.","hint":"Moyen mnémotechnique anglais : « Seven-five – man with a knife » (homme avec un couteau)."},"q018":{"q":"Quel est le code VFR standard en Suisse et dans la plupart des pays d'Europe ?","options":["2000","7000","1200","0000"],"explain":"7000 est le code VFR en Europe (1200 est utilisé aux États-Unis).","hint":"Le code VFR aux États-Unis est 1200 – en Europe c'est un autre."},"q019":{"q":"Deux aéronefs de la même catégorie convergent à peu près au même niveau. Qui cède le passage ?","options":["Le plus rapide","Celui qui a l'autre à sa droite","Celui qui a l'autre à sa gauche","Le plus haut"],"explain":"L'aéronef qui a l'autre à sa droite cède le passage.","hint":"Comme à beaucoup de carrefours : priorité de droite."},"q020":{"q":"Deux aéronefs se rapprochent de face. Que font-ils ?","options":["Les deux virent à gauche","Les deux virent à droite","Les deux montent","Le plus bas descend"],"explain":"Les deux modifient leur cap vers la droite.","hint":"Même idée que deux navires qui se croisent – les deux tournent du même côté."},"q021":{"q":"Tu dépasses un autre aéronef. Comment le dépasses-tu ?","options":["Par sa gauche","Par sa droite, en modifiant ton cap vers la droite","Par-dessus","Par-dessous"],"explain":"L'aéronef qui dépasse s'écarte en modifiant son cap vers la droite.","hint":"Celui qui dépasse cède le passage et passe du même côté que pour la règle de face."},"q022":{"q":"Deux aéronefs sont en finale. Lequel a la priorité ?","options":["Le plus haut","Le plus rapide","Le plus bas","Celui qui a appelé en premier"],"explain":"L'aéronef le plus bas a la priorité, mais ne doit pas couper la route ni dépasser un aéronef en finale.","hint":"L'avion le plus proche du sol a moins de marge de manœuvre."},"q023":{"q":"Signal lumineux de la tour à un aéronef en vol : vert fixe.","options":["Autorisé à atterrir","Revenez pour atterrir","Cédez le passage, continuez à tourner","Aérodrome dangereux, n'atterrissez pas"],"explain":"Vert fixe en vol = autorisé à atterrir.","hint":"Vert et fixe = vas-y."},"q024":{"q":"Signal lumineux à un aéronef en vol : rouge clignotant.","options":["Autorisé à atterrir","Aérodrome dangereux, n'atterrissez pas","Cédez le passage, continuez à tourner","Revenez pour atterrir"],"explain":"Rouge clignotant en vol = aérodrome dangereux, n'atterrissez pas.","hint":"Rouge clignotant en vol = c'est l'aérodrome lui-même le problème."},"q025":{"q":"Signal lumineux à un aéronef en vol : rouge fixe.","options":["Cédez le passage aux autres aéronefs et continuez à tourner","N'atterrissez pas","Autorisé à atterrir","Atterrissez immédiatement"],"explain":"Rouge fixe en vol = cédez le passage aux autres aéronefs et continuez à tourner.","hint":"Rouge fixe en vol = pas toi, pas maintenant – continue à tourner."},"q026":{"q":"Signal lumineux à un aéronef au sol : blanc clignotant.","options":["Autorisé à rouler","Arrêtez","Retournez au point de départ sur l'aérodrome","Dégagez l'aire d'atterrissage"],"explain":"Blanc clignotant au sol = retournez au point de départ sur l'aérodrome.","hint":"Blanc clignotant au sol = retourne d'où tu viens."},"q027":{"q":"Signal lumineux à un aéronef au sol : vert clignotant.","options":["Autorisé à décoller","Autorisé à rouler","Arrêtez","Retournez au point de départ"],"explain":"Vert clignotant au sol = autorisé à rouler.","hint":"Au sol, le vert clignotant te permet de bouger."},"q028":{"q":"Hauteur minimale au-dessus des zones à forte densité des villes, villages ou agglomérations (SERA, VFR) :","options":["500 ft au-dessus de l'obstacle le plus élevé dans un rayon de 150 m","1000 ft au-dessus de l'obstacle le plus élevé dans un rayon de 600 m","1500 ft au-dessus du sol","2000 ft au-dessus de l'obstacle le plus élevé dans un rayon de 1 km"],"explain":"1000 ft au-dessus de l'obstacle le plus élevé dans un rayon de 600 m autour de l'aéronef. Sauf pour le décollage et l'atterrissage.","hint":"Plus de hauteur, plus grand rayon au-dessus des agglomérations."},"q029":{"q":"Hauteur minimale ailleurs (zones non denses), VFR :","options":["300 ft au-dessus du sol ou de l'eau","500 ft au-dessus du sol ou de l'eau","1000 ft au-dessus du sol","Aucun minimum"],"explain":"500 ft au-dessus du sol ou de l'eau, ou 500 ft au-dessus de l'obstacle le plus élevé dans un rayon de 150 m. Sauf pour le décollage et l'atterrissage.","hint":"La moitié de la valeur au-dessus des agglomérations."},"q030":{"q":"Minima VMC dans les espaces aériens C, D et E en dessous du FL100 :","options":["1,5 km de visibilité, hors des nuages","5 km de visibilité, 1500 m horizontalement et 1000 ft verticalement des nuages","8 km de visibilité, 1500 m et 1000 ft des nuages","5 km de visibilité, 300 m des nuages"],"explain":"En dessous du FL100 : 5 km de visibilité en vol, 1500 m horizontalement et 1000 ft verticalement des nuages.","hint":"Retiens 5 – 1500 – 1000 en dessous du FL100."},"q031":{"q":"Minima VMC dans les espaces aériens C, D et E au FL100 et au-dessus :","options":["5 km de visibilité","8 km de visibilité, 1500 m et 1000 ft des nuages","10 km de visibilité, hors des nuages","8 km de visibilité, hors des nuages"],"explain":"Au FL100 et au-dessus, la visibilité en vol passe à 8 km.","hint":"Plus haut et plus vite – la visibilité exigée augmente."},"q032":{"q":"VMC standard SERA en classe G à 3000 ft AMSL ou en dessous (ou 1000 ft au-dessus du relief, la plus élevée des deux) :","options":["5 km de visibilité, hors des nuages et en vue de la surface","1,5 km de visibilité, 1000 ft des nuages","8 km de visibilité","Aucun minimum"],"explain":"5 km, hors des nuages et en vue de la surface. Les États peuvent autoriser une visibilité inférieure à basse vitesse – vérifie les règles nationales (AIP).","hint":"Bas et lent en G : hors des nuages et en vue du sol."},"q033":{"q":"Pour entrer en VFR (sans VFR spécial) dans une zone de contrôle ou dans le circuit de piste, le plafond et la visibilité au sol minimaux sont :","options":["1000 ft et 3 km","1500 ft et 5 km","2000 ft et 8 km","500 ft et 1,5 km"],"explain":"Plafond d'au moins 1500 ft et visibilité au sol d'au moins 5 km.","hint":"La même visibilité que les VMC de base, et un plafond de 1500 ft."},"q034":{"q":"Quand un plan de vol est-il requis pour un vol VFR ?","options":["Pour chaque vol","Pour les vols franchissant une frontière internationale","Seulement pour les vols au-dessus du FL100","Seulement de nuit"],"explain":"Entre autres, un plan de vol est requis pour tout vol franchissant une frontière internationale, sauf si les États concernés en disposent autrement.","hint":"Pense au fait de quitter le pays."},"q035":{"q":"Vol VFR à plus de 3000 ft sol, route magnétique 070°. Quelle altitude de croisière est correcte ?","options":["4000 ft","4500 ft","5500 ft","6000 ft"],"explain":"Route magnétique 000°–179° : milliers impairs + 500 ft (3500, 5500, 7500 ft …). Au-dessus de l'altitude de transition en niveaux de vol (FL75, FL95 …).","hint":"Vers l'est (000°–179°) = milliers impairs + 500."},"q036":{"q":"Vol VFR à plus de 3000 ft sol, route magnétique 250°. Quelle altitude de croisière est correcte ?","options":["5500 ft","6500 ft","7500 ft","5000 ft"],"explain":"Route magnétique 180°–359° : milliers pairs + 500 ft (4500, 6500, 8500 ft …). Au-dessus de l'altitude de transition en niveaux de vol.","hint":"Vers l'ouest (180°–359°) = milliers pairs + 500."},"q037":{"q":"Qui décide en dernier ressort si un vol a lieu ?","options":["L'école de vol","Le contrôle de la circulation aérienne","Le commandant de bord (PIC)","Le propriétaire de l'aéronef"],"explain":"Le PIC est responsable de l'exploitation et de la sécurité de l'aéronef et décide de voler ou non.","hint":"Qui signe le vol et en porte la responsabilité ?"},"q038":{"q":"Avec une qualification de classe SEP échue, mais une PPL et un certificat médical valables, tu peux encore voler seul comme PIC sur un avion SEP.","explain":"Non. La qualification de classe doit être valable pour agir comme PIC. Après l'échéance, un contrôle de compétences (et éventuellement une formation) est nécessaire.","hint":"Licence, qualification et certificat médical doivent tous être valables en même temps."},"q039":{"q":"Température ISA au niveau moyen de la mer :","options":["0 °C","10 °C","15 °C","20 °C"],"explain":"ISA au MSL : 15 °C, 1013,25 hPa.","hint":"Une douce journée de printemps à la plage."},"q040":{"q":"Pression ISA au niveau moyen de la mer :","options":["1000 hPa","1013.25 hPa","1020 hPa","29.92 hPa"],"explain":"1013,25 hPa (= 29,92 inHg).","hint":"Le calage altimétrique standard."},"q041":{"q":"Gradient de température ISA dans la troposphère :","options":["1 °C par 1000 ft","2 °C par 1000 ft","3 °C par 1000 ft","0,5 °C par 1000 ft"],"explain":"Environ 2 °C par 1000 ft (0,65 °C par 100 m).","hint":"Environ 0,65 °C par 100 m."},"q042":{"q":"Quelle est la température ISA à 5000 ft ?","explain":"15 °C − 5 × 2 °C = 5 °C.","hint":"Retire 2 °C par 1000 ft à partir de 15 °C."},"q043":{"q":"Température 20 °C, point de rosée 12 °C. Estime la base des cumulus (ft au-dessus du sol).","explain":"Écart × 400 ft : 8 × 400 = 3200 ft (ou écart × 125 m).","hint":"Écart (T − Td) × 400 ft."},"q044":{"q":"Gradient adiabatique sec (air non saturé ascendant) :","options":["Environ 1 °C par 100 m","Environ 0,5 °C par 100 m","Environ 2 °C par 100 m","0 °C – la température reste constante"],"explain":"Environ 1 °C par 100 m (3 °C par 1000 ft). L'air saturé se refroidit plus lentement (environ 0,6 °C par 100 m).","hint":"L'air non saturé se refroidit plus vite que le gradient ISA."},"q045":{"q":"Dans un METAR, BKN signifie :","options":["1–2 octas","3–4 octas","5–7 octas","8 octas"],"explain":"FEW 1–2, SCT 3–4, BKN 5–7, OVC 8 octas.","hint":"Broken = plus de la moitié du ciel, mais pas tout."},"q046":{"q":"CAVOK signifie :","options":["Visibilité ≥ 5 km, pas de nuages sous 3000 ft","Visibilité ≥ 10 km, pas de nuages sous 5000 ft (ou MSA si plus élevée), pas de CB/TCU, pas de temps significatif","Ciel clair, pas de vent","Plafond au-dessus de 1500 ft"],"explain":"Visibilité de 10 km ou plus, pas de nuages sous 5000 ft ou l'altitude minimale de secteur la plus élevée, pas de CB ni de TCU, pas de temps significatif.","hint":"Ceiling And Visibility OK – pense à 10 km et 5000 ft."},"q047":{"q":"Dans un METAR ou un TAF, la direction du vent se réfère :","options":["Au nord magnétique","Au nord vrai","Au nord du quadrillage","À l'orientation de la piste"],"explain":"METAR/TAF : nord vrai. Vent donné par la tour ou l'ATIS : magnétique.","hint":"Les messages écrits utilisent une référence, les informations ATC parlées une autre."},"q048":{"q":"Dans un TAF, TEMPO signifie :","options":["Un changement permanent","Des fluctuations temporaires, chacune de moins d'1 heure et au total moins de la moitié de la période","Une probabilité de 30 %","La prévision est annulée"],"explain":"TEMPO : fluctuations temporaires, chacune de moins d'1 h, ensemble moins de la moitié de la période.","hint":"Temporary – bref et pas la plupart du temps."},"q049":{"q":"Le brouillard de rayonnement se forme typiquement avec :","options":["Vent fort et ciel couvert","Ciel clair, vent faible et forte humidité la nuit","Le passage d'un front chaud","Des orages"],"explain":"Nuit claire (le sol se refroidit par rayonnement), vent faible et air humide près du sol.","hint":"Le sol doit beaucoup se refroidir pendant la nuit."},"q050":{"q":"Quel nuage est typique des ondes orographiques (p. ex. par foehn) ?","options":["Cumulonimbus","Altocumulus lenticularis","Nimbostratus","Cirrus"],"explain":"Les nuages lenticulaires (ACSL) indiquent des ondes stationnaires – s'attendre à de la turbulence et à des rotors en dessous.","hint":"En forme de lentille ou d'OVNI."},"q051":{"q":"Le foehn sur le versant nord des Alpes apporte :","options":["De l'air froid et humide et du brouillard","Un vent chaud, sec et en rafales avec de la turbulence sous le vent","Uniquement des orages","Des conditions calmes"],"explain":"Vent descendant chaud, sec, souvent en rafales sous le vent ; forte turbulence et rotors près des montagnes.","hint":"L'air est comprimé et réchauffé en descendant du côté sous le vent."},"q052":{"q":"Remets les stades d'un orage dans l'ordre.","items":["Stade cumulus (développement)","Stade de maturité","Stade de dissipation"],"explain":"Stade cumulus (ascendances) → stade de maturité (ascendances et rabattants, fortes précipitations, dangers maximaux) → stade de dissipation (rabattants).","hint":"Croissance – maturité – dissipation."},"q053":{"q":"À quel stade d'un orage les ascendances et rabattants sont-ils les plus forts ?","options":["Stade cumulus","Stade de maturité","Stade de dissipation","Partout pareil"],"explain":"Le stade de maturité commence quand les précipitations atteignent le sol – turbulence, cisaillement du vent, grêle et foudre les plus forts.","hint":"Quand la pluie et la grêle commencent à tomber du nuage."},"q054":{"q":"Un front chaud approche. Remets les nuages dans l'ordre où tu les vois.","items":["Cirrus","Cirrostratus","Altostratus","Nimbostratus"],"explain":"Cirrus → cirrostratus (halo) → altostratus → nimbostratus avec pluie continue.","hint":"D'abord les nuages élevés, le nuage de pluie le plus bas en dernier."},"q055":{"q":"Quand le risque de givrage du carburateur est-il élevé ?","options":["Seulement en dessous de 0 °C","Seulement dans les nuages","Avec de l'air humide et des températures douces (même au-dessus de +20 °C), surtout à faible puissance","Seulement à pleine puissance"],"explain":"L'évaporation du carburant et l'effet venturi refroidissent l'air jusqu'à 20–30 °C. Risque maximal avec forte humidité, températures douces et faible puissance (descente).","hint":"Ce n'est pas qu'un problème d'hiver."},"q056":{"q":"Le point de rosée est :","options":["La température à laquelle l'air devient saturé en se refroidissant","La température de congélation de l'eau","La température au sommet des nuages","La température du sol la nuit"],"explain":"Refroidi jusqu'à son point de rosée, l'air est saturé – nuages ou brouillard se forment.","hint":"Refroidis assez l'air et il ne peut plus contenir davantage d'eau."},"q057":{"q":"Quels dangers sont liés à un cumulonimbus ?","options":["Turbulence et cisaillement du vent","Grêle et givrage","Foudre","Tous ces dangers"],"explain":"Forte turbulence, cisaillement du vent, grêle, givrage, foudre et fortes pluies. Garder une grande distance (souvent recommandé : au moins 10 NM).","hint":"Un CB a (presque) tout ce que tu ne veux pas."},"q142":{"q":"La bise sur le Plateau suisse est :","options":["Un vent chaud et sec descendant du sud","Un vent froid et sec du nord-est, souvent en rafales et turbulent près du sol","Une brise de mer","Une rafale descendante d'orage"],"explain":"De l'air continental froid s'écoule du nord-est entre le Jura et les Alpes ; il est canalisé et le plus fort dans les rétrécissements comme la région lémanique. Attends-toi à de la turbulence à basse altitude.","hint":"Elle vient du nord-est et elle est froide."},"q143":{"q":"En hiver, le Plateau est souvent sous une couche grise (stratus/brouillard élevé) alors que les Alpes sont ensoleillées. Pourquoi ?","options":["Un front chaud","Une inversion de température retient l'air froid et humide en dessous","Le fœhn","Une dépression sur les Alpes"],"explain":"Par haute pression, l'air froid s'accumule sur le Plateau ; l'inversion au-dessus empêche le brassage, un stratus bas se forme en dessous tandis qu'il fait clair au-dessus.","hint":"De l'air chaud repose sur de l'air froid."},"q144":{"q":"Dans le GAFOR suisse, que signifie la catégorie X ?","options":["Ouvert","Difficile","Critique","Fermé"],"explain":"Catégories GAFOR : O ouvert – D difficile – M critique – X fermé (pour la route, par rapport à son altitude de référence). Théorie seulement – consulte toujours la prévision officielle actuelle.","hint":"O, D, M, X – du meilleur au pire."},"q145":{"q":"Le givrage de la cellule est le plus probable :","options":["En air clair sous 0 °C","Dans les nuages ou la pluie entre environ 0 °C et −15 °C (gouttelettes surfondues)","Seulement sous −40 °C","Seulement au-dessus de l'isotherme zéro en air clair"],"explain":"Les gouttelettes d'eau surfondues gèlent à l'impact. Le plus fréquent de 0 °C à environ −15 °C ; la pluie verglaçante est particulièrement dangereuse. Connais l'isotherme zéro avant chaque vol.","hint":"L'eau peut rester liquide sous 0 °C – jusqu'à ce qu'elle touche ton aile."},"q058":{"q":"Combien de mètres fait 1 mille nautique ?","explain":"1 NM = 1852 m = 1 minute de latitude.","hint":"Une minute de latitude."},"q059":{"q":"Vitesse sol 100 kt, distance 45 NM. Combien de minutes ?","explain":"45 / 100 × 60 = 27 min.","hint":"Distance ÷ vitesse × 60."},"q060":{"q":"Vitesse sol 90 kt. Quelle distance parcours-tu en 40 minutes ?","explain":"90 × 40 / 60 = 60 NM.","hint":"Vitesse × temps (en heures)."},"q061":{"q":"Route vraie 090°, déclinaison 3° E. Quelle est la route magnétique ?","explain":"East is least : 090 − 3 = 087°.","hint":"Moyen mnémotechnique anglais : « East is least, west is best » (du vrai au magnétique)."},"q062":{"q":"Route magnétique 245°, déclinaison 2° W. Quelle est la route vraie ?","explain":"West is best : MC = TC + W, donc TC = 245 − 2 = 243°.","hint":"Du magnétique au vrai : inverse la règle."},"q063":{"q":"Règle du 1 sur 60 : après 30 NM, tu es à 3 NM de la route. Quelle est l'erreur de route en degrés ?","explain":"Erreur de route = écart × 60 / distance = 3 × 60 / 30 = 6°.","hint":"Écart de route × 60 ÷ distance parcourue."},"q064":{"q":"Les lignes reliant les points de même déclinaison magnétique s'appellent :","options":["Isobares","Isogones","Seulement agones","Isothermes"],"explain":"Isogones (l'agone est la ligne de déclinaison 0°).","hint":"« Iso » = égal, « gone » = angle."},"q065":{"q":"L'erreur du compas due aux champs magnétiques de l'aéronef s'appelle :","options":["Déclinaison","Déviation","Inclinaison","Dérive"],"explain":"Déviation – indiquée sur la carte de déviation du compas.","hint":"La déclinaison vient de la Terre, cette erreur vient de l'avion."},"q066":{"q":"En Suisse, il est 14:30 heure locale en été (HAEC). Quelle heure est-il en UTC ?","options":["12:30","13:30","14:30","15:30"],"explain":"Heure d'été HAEC = UTC+2, heure d'hiver HEC = UTC+1.","hint":"L'heure d'été suisse est UTC+2."},"q067":{"q":"5000 ft font environ combien de mètres ?","explain":"1 ft = 0,3048 m → 5000 × 0,3048 = 1524 m.","hint":"1 ft ≈ 0,3 m."},"q068":{"q":"Sur une carte au 1:500 000, 1 cm correspond à :","options":["500 m","5 km","50 km","1 NM"],"explain":"1 cm × 500 000 = 5 km.","hint":"500 000 cm = 5000 m."},"q069":{"q":"Une minute de latitude correspond à :","options":["1 km","1 NM","1 mille terrestre","60 NM"],"explain":"1′ de latitude = 1 NM (1° = 60 NM).","hint":"60 d'entre elles font un degré, soit 60 NM."},"q070":{"q":"Un radial VOR est :","options":["Le relèvement magnétique VERS la station","Le relèvement magnétique DEPUIS la station","Le relèvement vrai vers la station","La distance DME"],"explain":"Un radial est le relèvement magnétique depuis la station.","hint":"Les radiales partent de la station comme des rayons."},"q071":{"q":"Correction de vent : TAS 100 kt, composante de vent traversier 10 kt. Angle de correction approximatif ?","explain":"Dérive maximale ≈ vent traversier × 60 / TAS = 10 × 60 / 100 = 6°.","hint":"Dérive max. ≈ vent traversier × 60 ÷ TAS."},"q072":{"q":"Altitude de l'aérodrome 1400 ft, QNH 1003 hPa. Altitude-pression ? (1 hPa ≈ 30 ft)","explain":"PA = altitude + (1013 − QNH) × 30 = 1400 + 10 × 30 = 1700 ft.","hint":"QNH inférieur à 1013 → l'altitude-pression est plus élevée. Environ 30 ft par hPa."},"q073":{"q":"Altitude de l'aérodrome 1300 ft, QNH 1013 hPa, OAT 30 °C. Estime l'altitude-densité.","explain":"ISA à 1300 ft ≈ 12,4 °C. DA ≈ PA + 120 × (OAT − ISA) = 1300 + 120 × 17,6 ≈ 3400 ft.","hint":"Trouve d'abord la température ISA à 1300 ft, puis 120 ft par °C au-dessus de l'ISA."},"q074":{"q":"Altitude-pression 5000 ft, OAT +25 °C. Estime l'altitude-densité.","explain":"ISA à 5000 ft = 5 °C, écart +20 °C. DA ≈ 5000 + 120 × 20 = 7400 ft.","hint":"L'ISA à 5000 ft est de 5 °C."},"q075":{"q":"Que signifie une altitude-densité élevée pour ton avion ?","options":["Roulage au décollage plus court","Décollage plus long et taux de montée plus faible","Plus de puissance moteur","Aucun effet"],"explain":"Air moins dense : moins de puissance moteur, moins de traction de l'hélice et de portance – distances de décollage et d'atterrissage plus longues, montée plus faible.","hint":"Air peu dense = moins de puissance, moins de portance."},"q076":{"q":"Lesquels de ces facteurs augmentent la distance de décollage ?","options":["Température élevée","Altitude élevée de l'aérodrome","Vent arrière ou herbe mouillée","Tous ces facteurs"],"explain":"Chaleur, altitude, vent arrière, pente montante, herbe molle ou mouillée, masse élevée – chacun allonge la distance. Utilise les tableaux de l'AFM/POH.","hint":"Chaud, haut, lourd, vent arrière et sol mou – tout joue contre toi."},"q077":{"q":"Vent 20 kt à 30° de la piste. Composante de vent traversier ?","explain":"Vent traversier = vent × sin(angle) = 20 × 0,5 = 10 kt.","hint":"sin 30° = 0,5."},"q078":{"q":"Vent 20 kt à 60° de la piste. Composante de vent traversier ?","explain":"20 × sin 60° ≈ 20 × 0,87 ≈ 17 kt.","hint":"sin 60° ≈ 0,87."},"q079":{"q":"Vent 20 kt à 60° de la piste. Composante de vent de face ?","explain":"Vent de face = vent × cos(angle) = 20 × 0,5 = 10 kt.","hint":"cos 60° = 0,5."},"q080":{"q":"Consommation 20 l/h. Combien de carburant pour 1 h 45 min ?","explain":"20 × 1,75 = 35 l.","hint":"1 h 45 min = 1,75 h."},"q081":{"q":"AVGAS 100LL, environ 0,72 kg/l. Quelle est la masse de 100 litres ?","explain":"100 × 0,72 = 72 kg.","hint":"Litres × masse volumique."},"q082":{"q":"10 gallons US font combien de litres ?","explain":"1 US gal ≈ 3,785 l → 37,9 l.","hint":"1 gallon US ≈ 3,8 litres."},"q083":{"q":"Masse et centrage : avion 550 kg au bras 0,40 m, pilote + passager 160 kg à 0,50 m, carburant 50 kg à 0,80 m. Où se trouve le centre de gravité (m) ?","explain":"Moments : 220 + 80 + 40 = 340 kg·m. Masse 760 kg. CG = 340 / 760 ≈ 0,447 m.","hint":"Centrage = moment total ÷ masse totale (moment = masse × bras de levier)."},"q084":{"q":"Effet d'un centre de gravité proche de la limite arrière :","options":["Plus stable, profondeur plus lourde","Moins stable, efforts de profondeur légers, sortie de décrochage et de vrille plus difficile","Aucun effet sur le pilotage","Seulement un roulage au décollage plus long"],"explain":"Un CG arrière réduit la stabilité longitudinale. Au-delà de la limite arrière, la sortie de décrochage ou de vrille peut devenir impossible.","hint":"Bras de levier court pour l'empennage = moins de stabilité."},"q085":{"q":"Vx est :","options":["Meilleur taux de montée","Meilleur angle de montée","Meilleure finesse","Vitesse à ne jamais dépasser"],"explain":"Vx = meilleur angle (plus de hauteur par distance, pour les obstacles). Vy = meilleur taux (plus de hauteur par temps).","hint":"Moyen mnémotechnique anglais : X = extra raide (angle), Y = yes, montée la plus rapide (taux)."},"q086":{"q":"Comment une masse plus élevée affecte-t-elle le vol plané ?","options":["La distance de plané diminue beaucoup","La vitesse de meilleure finesse augmente, la distance de plané reste à peu près la même","La vitesse de meilleure finesse diminue","Aucun effet"],"explain":"La finesse maximale reste à peu près la même, mais elle est atteinte à une vitesse plus élevée.","hint":"Le rapport reste, la vitesse change."},"q087":{"q":"Réserve finale de carburant pour un vol VFR de jour (pas un vol local en vue de l'aérodrome), Part-NCO :","options":["10 minutes","30 minutes","45 minutes","60 minutes"],"explain":"30 minutes à l'altitude de croisière normale de jour (10 minutes pour les vols locaux en vue de l'aérodrome). C'est le minimum légal – ton club, ton école de vol ou l'exploitant de l'avion peut exiger davantage (p. ex. 45 ou 60 minutes). Leurs règles s'appliquent. Prévois quand même plus – les réserves sont pour l'imprévu.","hint":"Une demi-heure – et vérifie ce que ton club exige."},"q088":{"q":"Une aile décroche lorsque :","options":["La vitesse descend sous une valeur fixe","L'angle d'incidence critique est dépassé","Le moteur tombe en panne","L'avion est trop lourd"],"explain":"Le décrochage dépend de l'angle d'incidence, pas de la vitesse – il peut survenir à toute vitesse et dans toute assiette.","hint":"C'est une question d'angle, pas de vitesse."},"q089":{"q":"Quel est le facteur de charge en virage en palier à 60° d'inclinaison ?","explain":"n = 1 / cos 60° = 2.","hint":"n = 1 ÷ cos(inclinaison)."},"q090":{"q":"Vitesse de décrochage ailes horizontales 50 kt. Vitesse de décrochage approximative en virage en palier à 60° d'inclinaison ?","explain":"Vs augmente avec √n = √2 ≈ 1,41 → 50 × 1,41 ≈ 71 kt.","hint":"Multiplie par √(facteur de charge)."},"q091":{"q":"Si tu doubles la vitesse (le reste étant égal), la portance devient :","options":["Deux fois plus grande","Quatre fois plus grande","La moitié","Inchangée"],"explain":"Portance ∝ v², donc vitesse double = portance quadruple.","hint":"La portance augmente avec le carré de la vitesse."},"q092":{"q":"Sortir les volets :","options":["Augmente la vitesse de décrochage","Abaisse la vitesse de décrochage et augmente la traînée","Réduit la traînée","N'a aucun effet sur la vitesse de décrochage"],"explain":"Les volets augmentent le C_L max (vitesse de décrochage plus basse) et ajoutent de la traînée.","hint":"Plus de portance à basse vitesse, mais rien n'est gratuit."},"q093":{"q":"Le lacet inverse à la mise en virage à gauche signifie :","options":["Le nez part vers la gauche","Le nez part vers la droite, à l'opposé du virage","L'avion monte","L'avion s'incline à droite"],"explain":"L'aileron qui s'abaisse (aile droite) crée plus de traînée – le nez part à l'opposé du virage. Coordonne avec le palonnier.","hint":"L'aileron qui descend produit plus de traînée."},"q094":{"q":"Sortie de vrille standard (sauf si ton AFM dit autrement) : remets les étapes dans l'ordre.","items":["Réduire au ralenti","Ailerons au neutre","Pied à fond à l'opposé","Profondeur vers l'avant jusqu'à l'arrêt de la rotation","Palonnier au neutre et ressource"],"explain":"PARE : Power ralenti – Ailerons neutres – Rudder (palonnier) opposé – Elevator (profondeur) en avant. Toujours suivre ton AFM.","hint":"PARE – Power, Ailerons, Rudder, Elevator (puissance, ailerons, direction, profondeur)."},"q095":{"q":"L'effet de sol à l'atterrissage provoque :","options":["Plus de traînée induite – l'avion descend plus vite","Moins de traînée induite – l'avion a tendance à flotter","Une vitesse de décrochage plus élevée","Seulement un moment piqueur"],"explain":"À environ une envergure du sol, la traînée induite diminue – l'avion flotte, surtout s'il est trop rapide.","hint":"Près du sol, les tourbillons marginaux sont plus faibles."},"q096":{"q":"La vitesse de manœuvre (VA) avec une masse plus faible :","options":["Augmente","Diminue","Reste la même","Égale VNE"],"explain":"VA diminue quand la masse diminue.","hint":"Un avion plus léger atteint sa charge limite à une vitesse plus faible."},"q097":{"q":"L'arc blanc de l'anémomètre indique :","options":["La plage d'utilisation normale","La plage d'utilisation des volets","La plage de prudence","Ne jamais dépasser"],"explain":"Arc blanc : plage des volets. Vert : normal. Jaune : prudence, air calme seulement. Trait rouge : VNE.","hint":"La couleur de l'arc où tu peux utiliser les volets."},"q098":{"q":"L'arc jaune de l'anémomètre signifie :","options":["Les volets peuvent être sortis","Prudence – seulement en air calme","Meilleure finesse","Plage de décrochage"],"explain":"Plage de prudence : voler seulement en air calme, pas de commandes brusques.","hint":"Jaune comme un panneau d'avertissement."},"q099":{"q":"Avec une hélice tournant dans le sens horaire (vue du cockpit), au décollage l'avion tend à :","options":["Partir à gauche – corriger avec le palonnier à droite","Partir à droite – corriger avec le palonnier à gauche","Piquer","Ne pas partir en lacet du tout"],"explain":"Le souffle de l'hélice, le facteur P et le couple font partir l'avion à gauche – il faut du palonnier à droite. Vérifie le sens de rotation de ton moteur.","hint":"Le souffle de l'hélice frappe le côté gauche de l'empennage."},"q100":{"q":"La traînée induite est la plus forte :","options":["À grande vitesse","À basse vitesse / grand angle d'incidence","À la vitesse de croisière","Elle est constante"],"explain":"La traînée induite diminue avec la vitesse ; la traînée parasite augmente avec la vitesse.","hint":"La traînée induite est le prix de la portance à grand angle d'attaque."},"q101":{"q":"Remets les temps d'un moteur à pistons à quatre temps dans l'ordre.","items":["Admission","Compression","Combustion-détente","Échappement"],"explain":"Admission → compression → combustion-détente → échappement.","hint":"Admission – compression – combustion – échappement."},"q102":{"q":"Pourquoi les moteurs à pistons d'avion ont-ils deux magnétos ? (moteur typique avec magnétos)","options":["Pour démarrer le moteur plus vite","Redondance et combustion plus complète (deux bougies par cylindre)","Pour alimenter la radio","Pour charger la batterie"],"explain":"Deux systèmes d'allumage indépendants : sécurité si l'un tombe en panne, meilleure combustion avec les deux.","hint":"Tout en double est plus sûr – et brûle mieux."},"q103":{"q":"Essai magnétos : aucune chute de régime en passant sur une magnéto. Que peut-ce signifier ? (moteur typique avec magnétos)","options":["Tout est parfait","La magnéto n'est peut-être pas à la masse (fil P coupé) – le moteur pourrait démarrer si l'on bouge l'hélice","La batterie est vide","Le mélange est trop pauvre"],"explain":"Aucune chute peut signifier une masse coupée (fil P) : la magnéto reste « chaude » même sur OFF. Considère l'hélice comme dangereuse et signale-le.","hint":"Une magnéto qui ne se coupe jamais est dangereuse au sol."},"q104":{"q":"Tu tires le réchauffage carburateur. Le régime chute, puis remonte lentement. Que cela signifie-t-il ?","options":["Il y avait de la glace au carburateur, elle fond","Le moteur surchauffe","La magnéto est en panne","Normal – pas de glace"],"explain":"L'air chaud est moins dense (chute de régime). Si la glace fond, le régime remonte.","hint":"D'abord la perte due à l'air chaud, puis la glace fond."},"q105":{"q":"Pourquoi appauvris-tu le mélange en montée ? (moteur typique avec réglage manuel du mélange)","options":["La densité de l'air diminue – le mélange devient trop riche","Pour refroidir le moteur","Pour augmenter la puissance avant tout","Ce n'est jamais nécessaire"],"explain":"Avec l'altitude, il y a moins d'air pour la même quantité de carburant : le mélange devient riche. Appauvrir selon l'AFM.","hint":"Moins d'air, autant de carburant."},"q106":{"q":"Qu'est-ce qui peut provoquer la détonation ?","options":["Mélange trop riche","Mélange trop pauvre, température élevée des cylindres ou carburant à indice d'octane trop bas","Faible puissance","Temps froid"],"explain":"Détonation = combustion explosive incontrôlée. Causes : mélange pauvre, températures élevées, mauvais carburant.","hint":"Chaud et pauvre, c'est mauvais pour le moteur."},"q107":{"q":"Le tube de Pitot et son trou de purge sont bouchés, la prise statique est ouverte. En montée, l'anémomètre :","options":["Indique trop peu","Indique une vitesse croissante – il agit comme un altimètre","Reste constant et correct","Indique zéro"],"explain":"La pression totale piégée reste la même pendant que la pression statique baisse – la vitesse indiquée augmente en montée.","hint":"Pression piégée dans la ligne pitot, pression statique extérieure qui baisse."},"q108":{"q":"La prise statique est bouchée. Qu'indiquent l'altimètre et le variomètre ?","options":["Altimètre figé, variomètre à zéro","Les deux fonctionnent normalement","Altimètre trop haut, variomètre trop haut","Altimètre à zéro"],"explain":"Aucune variation de pression statique : l'altimètre reste sur la même valeur, le variomètre indique zéro. Utilise la prise statique de secours.","hint":"Aucune variation de pression statique n'atteint les instruments."},"q109":{"q":"À quelle fréquence faut-il recaler le conservateur de cap sur le compas magnétique ?","options":["Jamais","Environ toutes les 15 minutes, en vol rectiligne en palier","Seulement avant le décollage","Toutes les heures"],"explain":"La précession du gyroscope fait dériver le conservateur de cap. Le recaler environ toutes les 15 minutes quand le compas est stable.","hint":"Les gyroscopes dérivent – un quart d'heure."},"q110":{"q":"Hémisphère nord, cap à l'est, tu accélères. Le compas magnétique indique :","options":["Un virage apparent vers le nord","Un virage apparent vers le sud","Aucun changement","Il tourne"],"explain":"ANDS : Accelerate → North, Decelerate → South (aux caps est/ouest).","hint":"Moyen mnémotechnique anglais : ANDS – Accelerate North, Decelerate South."},"q111":{"q":"La bille est décalée vers la droite. Que fais-tu ?","options":["Pied à gauche","Pied à droite","Pousser le manche","Réduire la puissance"],"explain":"« Marcher sur la bille » : palonnier à droite pour la centrer.","hint":"Marche sur la bille."},"q112":{"q":"De quelle couleur est l'AVGAS 100LL ?","options":["Rouge","Vert","Bleu","Incolore"],"explain":"L'AVGAS 100LL est teinté en bleu. Le Jet A-1 est incolore à jaune paille.","hint":"La même couleur que beaucoup de lacs par une journée ensoleillée."},"q113":{"q":"Symptôme précoce typique de l'hypoxie :","options":["Douleur aux oreilles","Euphorie et jugement altéré – souvent sans s'en rendre compte","Faim","Éternuements"],"explain":"L'hypoxie s'installe insidieusement : euphorie, pensée plus lente, mauvaises décisions – le pilote ne le remarque souvent pas.","hint":"Le danger : tu te sens bien."},"q114":{"q":"Part-NCO : quand le pilote doit-il utiliser de l'oxygène d'appoint ?","options":["Toujours au-dessus de 8000 ft","Altitude cabine au-dessus de 10 000 ft pendant plus de 30 minutes, et toujours au-dessus de 13 000 ft","Seulement au-dessus du FL200","Jamais en vol non commercial"],"explain":"Au-dessus de 10 000 ft plus de 30 min et toujours au-dessus de 13 000 ft d'altitude cabine.","hint":"Deux seuils : 10 000 ft pendant un certain temps, 13 000 ft immédiatement."},"q115":{"q":"Une piste montante te donne l'impression :","options":["D'être trop bas – tu as tendance à faire l'approche trop haut","D'être trop haut – tu as tendance à faire l'approche trop bas","Rien de particulier","D'être trop rapide"],"explain":"Les pistes montantes (et étroites) donnent l'impression d'être haut – risque d'approche trop basse.","hint":"Une piste montante donne l'impression d'être trop haut."},"q116":{"q":"Une piste plus large que d'habitude te donne l'impression :","options":["D'être trop haut","D'être trop bas – risque d'arrondir trop haut","D'être trop rapide","Rien de particulier"],"explain":"Une piste large paraît plus proche – tu te sens bas et risques d'arrondir trop haut.","hint":"Une grande piste paraît plus proche."},"q117":{"q":"Tu soupçonnes du monoxyde de carbone dans le cockpit (maux de tête, somnolence). Que fais-tu ?","options":["Allumer le chauffage","Chauffage coupé, aérations d'air frais ouvertes, atterrir dès que possible","Monter plus haut","L'ignorer"],"explain":"Le CO est inodore et vient de l'échappement via le chauffage. Chauffage coupé, air frais, atterrir rapidement.","hint":"D'abord arrêter la source, puis de l'air frais."},"q118":{"q":"Bonne technique de surveillance du ciel :","options":["Fixer un point","Courts mouvements des yeux par secteurs d'environ 10°, environ 1 seconde chacun","Regarder seulement droit devant","Utiliser seulement l'affichage du trafic"],"explain":"L'œil a besoin de fixer pour détecter des objets. Balaie le ciel secteur par secteur.","hint":"L'œil doit s'arrêter pour voir quelque chose."},"q119":{"q":"Après un long virage régulier, tu remets les ailes à plat et te sens incliné de l'autre côté. Cette illusion s'appelle :","options":["Illusion somatogravique","The leans (illusion d'inclinaison)","Black hole","Autocinèse"],"explain":"L'oreille interne s'habitue à un virage constant ; la sortie ressemble à un virage de l'autre côté. Fais confiance aux instruments/à l'horizon.","hint":"Ton oreille interne s'est habituée au virage."},"q120":{"q":"Une forte accélération au décollage (par mauvaise visibilité) peut donner l'impression :","options":["D'une assiette piquée","D'une assiette cabrée – risque de pousser le nez vers le bas","D'un virage","De rien"],"explain":"Illusion somatogravique : l'accélération donne l'impression de cabrer.","hint":"L'accélération te plaque dans le siège."},"q121":{"q":"Que signifie le « I » de la check-list IMSAFE ?","options":["Instruments","Illness (maladie)","Insurance","Identification"],"explain":"Illness – Medication – Stress – Alcohol – Fatigue – Eating/Emotion.","hint":"La première chose à vérifier, c'est ta propre santé."},"q146":{"q":"Tu as fait de la plongée ce matin (sans paliers de décompression). Que recommande-t-on en général avant de voler ?","options":["Tu peux voler tout de suite","Attendre au moins 12 heures (au moins 24 heures après des plongées avec paliers)","Attendre 2 heures","Voler seulement sous 1000 ft"],"explain":"L'azote dissous dans le corps peut former des bulles à pression cabine plus basse (accident de décompression). Recommandation courante : 12 h, ou 24 h après des plongées avec paliers. Demande à ton médecin-examinateur (AME).","hint":"L'azote dissous a besoin de temps pour quitter le corps."},"q147":{"q":"Tu as donné ton sang aujourd'hui. Que recommande-t-on en général ?","options":["Aucune restriction","Ne pas voler comme pilote pendant au moins 24 heures","Voler seulement avec un passager","Attendre 2 heures"],"explain":"La perte de sang peut provoquer vertiges ou évanouissement, surtout en altitude. On recommande couramment de ne pas voler pendant au moins 24 heures – demande à ton médecin-examinateur (AME).","hint":"Moins de sang = moins de transport d'oxygène."},"q148":{"q":"Tu es enrhumé et tu as le nez bouché. Quel est le risque principal en vol ?","options":["Aucun","Douleurs et lésions des oreilles ou des sinus, surtout en descente, car la pression ne peut pas s'équilibrer","Hypoxie à basse altitude","Seulement des éternuements"],"explain":"Des trompes d'Eustache ou des sinus bouchés ne peuvent pas équilibrer la pression – fortes douleurs ou barotraumatisme, surtout en descente. Ne vole pas enrhumé ; les décongestionnants peuvent cesser d'agir en vol.","hint":"La pression doit s'équilibrer – des conduits bouchés n'y arrivent pas."},"q122":{"q":"Les tourbillons de sillage :","options":["Montent et restent là où ils ont été créés","Descendent lentement et dérivent avec le vent","N'existent qu'en croisière","Sont les plus forts derrière un avion léger et rapide"],"explain":"Les tourbillons descendent et dérivent avec le vent. Reste au-dessus et au vent de la trajectoire de l'avion plus gros.","hint":"De l'air lourd tourbillonne derrière les ailes – où va-t-il ?"},"q123":{"q":"Quand la turbulence de sillage est-elle la plus forte ?","options":["Avion lourd, lisse et lent","Avion léger et rapide","Avion volets entièrement sortis à grande vitesse","Planeurs"],"explain":"Lourd, lisse (volets rentrés) et lent – typique juste après le décollage et en approche.","hint":"Lourd, lisse et lent signifie grand angle d'attaque."},"q124":{"q":"Atterrissage après un avion plus gros sur la même piste :","options":["Toucher avant son point de toucher","Toucher après son point de toucher et rester au-dessus de sa trajectoire d'approche","Atterrir le plus tôt possible","Atterrir exactement au même point"],"explain":"Reste au-dessus de sa trajectoire et atterris au-delà du point où il a touché.","hint":"Reste au-dessus et atterris après son point de toucher."},"q125":{"q":"Fréquence internationale de détresse aéronautique :","options":["118.000 MHz","121.500 MHz","123.450 MHz","406.000 MHz"],"explain":"121.500 MHz (fréquence VHF de détresse/veille).","hint":"La fréquence de veille internationale en VHF."},"q126":{"q":"Les ELT modernes émettent vers les satellites sur :","options":["121.5 MHz seulement","406 MHz (avec 121.5 MHz pour le radioralliement)","243 MHz seulement","118 MHz"],"explain":"406 MHz vers COSPAS-SARSAT, 121.5 MHz comme signal de radioralliement.","hint":"Les satellites écoutent sur une fréquence bien plus élevée."},"q127":{"q":"Panne moteur juste après le décollage à basse hauteur :","options":["Faire immédiatement demi-tour vers la piste","Baisser le nez, meilleure finesse, atterrir à peu près droit devant","Monter pour gagner de la hauteur","Essayer de redémarrer avant tout"],"explain":"Pilote l'avion : meilleure finesse et atterris devant dans un petit angle. Un demi-tour à basse hauteur se termine souvent par un décrochage.","hint":"La vitesse d'abord – faire demi-tour à basse hauteur est le piège classique."},"q128":{"q":"Priorités dans toute situation anormale – remets-les dans l'ordre.","items":["Aviate (piloter)","Navigate (naviguer)","Communicate (communiquer)"],"explain":"Aviate – Navigate – Communicate, aussi appelé Fly – Nav – Com : d'abord piloter l'avion, puis savoir où aller, puis parler.","hint":"Fly – Nav – Com."},"q129":{"q":"Remets les branches d'un circuit de piste dans l'ordre, en commençant après le décollage.","items":["Montée dans l'axe (Upwind / Climb-out)","Vent traversier (Crosswind)","Vent arrière (Downwind)","Base","Finale"],"explain":"Montée dans l'axe (Upwind) → vent traversier (Crosswind) → vent arrière (Downwind) → base → finale.","hint":"Up, cross, down, base, final – montée, vent traversier, vent arrière, base, finale."},"q130":{"q":"Sauf publication contraire, les circuits de piste se font :","options":["À droite","À gauche","Dans les deux sens","Uniquement en approche directe"],"explain":"Le standard est à gauche. Vérifie toujours la VAC – beaucoup d'aérodromes suisses ont des circuits à droite pour certaines pistes.","hint":"Dans la plupart des avions, les pilotes sont assis à gauche."},"q131":{"q":"La piste « 26 » signifie que l'orientation de la piste est d'environ :","options":["026° vrai","260° magnétique","260° vrai","026° magnétique"],"explain":"Numéro de piste = orientation magnétique arrondie à 10°, divisée par 10.","hint":"Ajoute un zéro ; les numéros de piste sont magnétiques."},"q132":{"q":"« WILCO » signifie :","options":["J'ai reçu votre message","J'ai compris votre message et je m'y conformerai","Répétez","Attendez"],"explain":"Will comply – j'ai compris et je le ferai.","hint":"WILl COmply – je vais m'y conformer."},"q133":{"q":"« ROGER » signifie :","options":["Oui","Je m'y conformerai","J'ai reçu la totalité de votre dernière transmission","Répétez"],"explain":"Roger = reçu. Ce n'est ni une réponse à une question ni un collationnement.","hint":"Seulement reçu – rien de plus."},"q134":{"q":"« AFFIRM » signifie :","options":["Oui","Non","Je m'y conformerai","Attendez"],"explain":"Affirm = oui. Negative = non.","hint":"Affirm ressemble à « affirmative » (affirmatif)."},"q135":{"q":"Lisibilité 5 signifie :","options":["Illisible","Lisible par moments","Lisible avec difficulté","Parfaitement lisible"],"explain":"1 illisible – 2 par moments – 3 avec difficulté – 4 lisible – 5 parfaitement lisible.","hint":"Le chiffre le plus élevé de l'échelle."},"q136":{"q":"Quels éléments doivent toujours être collationnés ?","options":["Les informations de vent","La piste, le calage altimétrique, le code SSR et les autorisations","Les informations de trafic","Les bulletins météo"],"explain":"Piste en service, autorisations, calages altimétriques, codes SSR, instructions de niveau/cap/vitesse (et changements de fréquence).","hint":"Tout ce qui change où tu vas ou comment tu règles tes instruments."},"q137":{"q":"« MAYDAY » est utilisé pour :","options":["L'urgence – un problème mais pas de danger immédiat","La détresse – danger grave et imminent, assistance immédiate nécessaire","Un essai radio","Un compte rendu de position"],"explain":"MAYDAY = détresse. PAN PAN = urgence.","hint":"Du français « m'aider »."},"q138":{"q":"Remets ces catégories de messages dans l'ordre de priorité (la plus haute d'abord).","items":["Détresse","Urgence","Sécurité des vols","Météorologie"],"explain":"Détresse → urgence → (radiogoniométrie) → sécurité des vols → météorologie → régularité des vols.","hint":"D'abord la vie, puis les problèmes urgents, puis la sécurité, puis la météo."},"q139":{"q":"« SQUAWK IDENT » signifie :","options":["Afficher le code 7000","Appuyer sur le bouton IDENT du transpondeur","Éteindre le transpondeur","Donner ton indicatif"],"explain":"Activer la fonction d'identification spéciale de position (IDENT).","hint":"Le bouton qui fait ressortir ton plot sur l'écran radar."},"q140":{"q":"Quelle heure est utilisée dans les communications radio aéronautiques ?","options":["L'heure locale","UTC","L'heure de l'aérodrome de départ","N'importe quelle heure"],"explain":"On utilise toujours l'UTC.","hint":"Les pilotes du monde entier utilisent la même horloge."}}`),r={version:e,categories:t,questions:n};export{t as categories,r as default,n as questions,e as version};